def validate_grid(grid: list[list[int]]) -> bool:
    if not isinstance(grid, list) or len(grid) != 9:
        return False
    cols: list[set[int]] = [set() for _ in range(9)]
    boxes: list[set[int]] = [set() for _ in range(9)]
    for r, row in enumerate(grid):
        if not isinstance(row, list) or len(row) != 9:
            return False
        seen_row: set[int] = set()
        for c, val in enumerate(row):
            if isinstance(val, bool) or not isinstance(val, int) or val < 0 or val > 9:
                return False
            if val != 0:
                b = (r // 3) * 3 + (c // 3)
                if val in seen_row or val in cols[c] or val in boxes[b]:
                    return False
                seen_row.add(val)
                cols[c].add(val)
                boxes[b].add(val)
    return True
```

### Unit Check
