def find_best_empty(grid: list[list[int]]) -> tuple[int, int, list[int]] | None:
    best: tuple[int, int, list[int]] | None = None
    for r in range(9):
        for c in range(9):
            if grid[r][c] == 0:
                cands = candidates(grid, r, c)
                if len(cands) == 0:
                    return (r, c, [])
                if best is None or len(cands) < len(best[2]):
                    best = (r, c, cands)
    return best
```

